 let night=false;function setNight(value){night=value;cloudMat.color.set(value?'#728995':'#fff9ec');cloudMat.opacity=1;birds.forEach(b=>b.gull.visible=!value);}
 function update(dt,t){const time=reduced.matches?0:t;waveTime.value=time;foam.forEach((o,i)=>{o.material.opacity=.12+Math.sin(time*.8+i*2)*.09;o.scale.setScalar(1+Math.sin(time*.4+i)*.004);});clouds.forEach((o,i)=>{o.position.x=o.userData.base.x+Math.sin(time*.035+i)*2;o.position.z=o.userData.base.z+Math.sin(time*.025+i)*1.5;});birds.forEach(({gull,wings,phase},i)=>{const a=time*.13+phase;gull.position.set(Math.cos(a)*(17+i%3*2),6+i%4*.8+Math.sin(a*2)*.3,Math.sin(a)*(21+i%3*3));gull.rotation.y=-a;wings.forEach((w,j)=>w.rotation.z=(j?1:-1)*(Math.sin(time*4+phase)*.35+.12));});boats.forEach((o,i)=>{o.position.y=-.4+Math.sin(time*.8+i)*.07;o.rotation.z=Math.sin(time*.7+i)*.035;o.rotation.y=i?.25:-.4;});whales.forEach(({object,base,phase})=>{const a=time*.12+phase;object.position.set(base.x+Math.cos(a)*2,-.89+Math.max(0,Math.sin(time*.32+phase))*.26,base.z+Math.sin(a)*2);object.rotation.y=-a;object.rotation.z=Math.sin(time*.7+phase)*.07;});dolphins.forEach(({object,base,phase})=>{const a=time*.22+phase;object.position.set(base.x+Math.sin(a)*1.4,-.71+Math.pow(Math.max(0,Math.sin(time*.65+phase)),5)*.50,base.z+Math.cos(a)*1.6);object.rotation.y=-a;object.rotation.z=Math.sin(time*1.7+phase)*.12;});turtles.forEach(({object,base,phase})=>{object.position.set(base.x+Math.sin(time*.12+phase)*2,-.69+Math.sin(time+phase)*.035,base.z+Math.cos(time*.16+phase)*1.7);object.rotation.y=time*.12+phase;});balloons.forEach(({object,base,phase})=>{object.position.set(base.x+Math.sin(time*.11+phase)*2,base.y+Math.sin(time*.5+phase)*.55,base.z+Math.cos(time*.09+phase)*1.6);object.rotation.z=Math.sin(time*.5+phase)*.035;});flowerBeds.forEach((bed,i)=>bed.rotation.z=Math.sin(time*.8+i)*.015);}
 return {update,setNight,audit:()=>({clouds:clouds.length,cloudStyles:3,seagulls:birds.length,boats:boats.length,whales:whales.length,dolphinPods:dolphins.length,turtles:turtles.length,hotAirBalloons:balloons.length,carnationBeds:flowerBeds.length,treeStyles:5,treeInstances:treeKinds,coastalDecor:decor,waves:true,reducedMotion:reduced.matches,night})};
